1	package events
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"time"
9	)
10	
11	// eventDTO is the wire and on-disk representation of an event. Timestamps use
12	// RFC3339Nano, which time.Time produces and accepts natively. Labels is
13	// omitted entirely when an event has none, so frames written before labels
14	// existed decode unchanged.
15	type eventDTO struct {
16		ID       string            `json:"id"`
17		Service  string            `json:"service"`
18		Severity string            `json:"severity"`
19		Message  string            `json:"message"`
20		At       time.Time         `json:"at"`
21		Labels   map[string]string `json:"labels,omitempty"`
22	}
23	
24	// labelsObject decodes the raw labels member strictly: it must be null or an
25	// object whose values are all strings, and duplicate names are rejected
26	// instead of silently overwriting each other the way a plain map decode
27	// would. Name/value content rules are enforced later by NormalizeLabels.
28	func decodeLabels(raw json.RawMessage) (map[string]string, error) {
29		if len(raw) == 0 || bytes.Equal(raw, []byte("null")) {
30			return nil, nil
31		}
32		dec := json.NewDecoder(bytes.NewReader(raw))
33		open, err := dec.Token()
34		if err != nil {
35			return nil, fmt.Errorf("decode labels: %w", err)
36		}
37		if delim, ok := open.(json.Delim); !ok || delim != '{' {
38			return nil, fmt.Errorf("decode labels: must be an object of string values")
39		}
40		labels := make(map[string]string)
41		for dec.More() {
42			keyToken, err := dec.Token()
43			if err != nil {
44				return nil, fmt.Errorf("decode labels: %w", err)
45			}
46			key, ok := keyToken.(string)
47			if !ok {
48				return nil, fmt.Errorf("decode labels: names must be strings")
49			}
50			if _, dup := labels[key]; dup {
51				return nil, fmt.Errorf("decode labels: duplicate label name %q", key)
52			}
53			var value *string
54			if err := dec.Decode(&value); err != nil {
55				return nil, fmt.Errorf("decode labels: value for %q must be a string", key)
56			}
57			if value == nil {
58				return nil, fmt.Errorf("decode labels: value for %q must be a string", key)
59			}
60			labels[key] = *value
61		}
62		if _, err := dec.Token(); err != nil { // closing '}'
63			return nil, fmt.Errorf("decode labels: %w", err)
64		}
65		if len(labels) == 0 {
66			return nil, nil
67		}
68		return labels, nil
69	}
70	
71	// rawEventDTO mirrors eventDTO but keeps labels unexamined so DecodeBatch can
72	// apply the strict duplicate-key and string-value checks.
73	type rawEventDTO struct {
74		ID       string          `json:"id"`
75		Service  string          `json:"service"`
76		Severity string          `json:"severity"`
77		Message  string          `json:"message"`
78		At       time.Time       `json:"at"`
79		Labels   json.RawMessage `json:"labels"`
80	}
81	
82	// MarshalBatch encodes normalized events as a JSON array with sorted keys.
83	func MarshalBatch(batch []Event) ([]byte, error) {
84		dtos := make([]eventDTO, len(batch))
85		for i, event := range batch {
86			dtos[i] = eventDTO{
87				ID:       event.ID,
88				Service:  event.Service,
89				Severity: event.Severity,
90				Message:  event.Message,
91				At:       event.At,
92				Labels:   event.Labels,
93			}
94		}
95		return json.Marshal(dtos)
96	}
97	
98	// DecodeBatch strictly decodes a JSON array of events. Unknown fields, syntax
99	// errors, malformed timestamps, malformed labels, and trailing data are
100	// rejected; callers remain responsible for emptiness and field validation.
101	func DecodeBatch(data []byte) ([]Event, error) {
102		dec := json.NewDecoder(bytes.NewReader(data))
103		dec.DisallowUnknownFields()
104		var dtos []rawEventDTO
105		if err := dec.Decode(&dtos); err != nil {
106			return nil, fmt.Errorf("decode events array: %w", err)
107		}
108		var extra json.RawMessage
109		if err := dec.Decode(&extra); err != io.EOF {
110			if err == nil {
111				return nil, fmt.Errorf("decode events array: unexpected trailing data")
112			}
113			return nil, fmt.Errorf("decode events array: %w", err)
114		}
115		batch := make([]Event, len(dtos))
116		for i, dto := range dtos {
117			labels, err := decodeLabels(dto.Labels)
118			if err != nil {
119				return nil, err
120			}
121			batch[i] = Event{
122				ID:       dto.ID,
123				Service:  dto.Service,
124				Severity: dto.Severity,
