		t.Fatalf("legacy dir second page: %d", status)
	}
	if len(out.Events) != 1 || out.Events[0]["id"] != "e2" {
		t.Fatalf("legacy dir second page: %v", out.Events)
	}
	p.signal(t, syscall.SIGTERM)
	p.waitExit(t, 0)
